interface.definition:
a!localVariables(
  local!coreAskDetails: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3235974"(
    returnCDT: true,
    fiscalYear: ri!fiscalYear,
    isActive: true,
    isCompleted: true,
    pagingInfo: #"SYSTEM_SYSRULES_pagingInfo"(
      startIndex: 1,
      batchSize: -1,
      sort: #"SYSTEM_SYSRULES_sortInfo"(
        field: "askDetailId"
      )
    )
  ),
  local!coreAskDetailsLatestCompletedVersion: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6753074"(
    asks: local!coreAskDetails
  ),
  local!plannedCoreAsks: sum(
    #"SYSTEM_SYSRULES_forEach"(
      items: local!coreAskDetailsLatestCompletedVersion,
      expression: fv!item.headCountAmount
    )
  ),
  local!actualCoreAsks: #"_a-0000e825-ace1-8000-9c24-011c48011c48_6911419"(
    fYear: ri!fiscalYear,
    returnCDT: true
  ),
  local!completedCoreAsks: sum(
    #"SYSTEM_SYSRULES_forEach"(
      items: local!actualCoreAsks,
      expression: if(
        fv!item.statusId = #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_5076350",
        1,
        0
      )
    )
  ),
  local!inprocessCoreAsks: length(local!actualCoreAsks) - local!completedCoreAsks,
  local!selectedGroupName,
  local!selectedGroups,
  local!fiscalYearLabel: "FY" & right(ri!fiscalYear, 2),
  local!groupChartData: #"_a-0000e825-ace1-8000-9c24-011c48011c48_6837454"(
    plan: local!coreAskDetailsLatestCompletedVersion,
    actualNominations: local!actualCoreAsks
  ),
  local!levelChartData: #"_a-0000e825-ace1-8000-9c24-011c48011c48_6892680"(
    plan: local!coreAskDetailsLatestCompletedVersion,
    actualNominations: local!actualCoreAsks
  ),
  local!groupSpecificChartData: #"_a-0000e825-ace1-8000-9c24-011c48011c48_6904936"(
    fiscalYear: ri!fiscalYear,
    selectedGroup: local!selectedGroups,
    actualNominations: local!actualCoreAsks
  ),
  {
    #"SYSTEM_SYSRULES_sectionLayout_v1"(
      contents: {
        #"SYSTEM_SYSRULES_columnsLayout"(
          columns: {
            #"SYSTEM_SYSRULES_columnLayout"(),
            #"SYSTEM_SYSRULES_columnLayout"(
              contents: #"SYSTEM_SYSRULES_sectionLayout_v1"(
                contents: {
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                    value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                      text: "FY " & ri!fiscalYear & " DPP Core",
                      color: "ACCENT",
                      size: "LARGE",
                      style: "STRONG"
                    ),
                    align: "CENTER"
                  ),
                  #"SYSTEM_SYSRULES_columnsLayout"(
                    columns: {
                      #"SYSTEM_SYSRULES_columnLayout"(
                        contents: #"SYSTEM_SYSRULES_cardLayout"(
                          contents: {
                            #"SYSTEM_SYSRULES_richTextDisplayField"(
                              value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                                text: local!plannedCoreAsks,
                                color: "ACCENT",
                                size: "LARGE",
                                style: "STRONG"
                              ),
                              align: "CENTER"
                            ),
                            #"SYSTEM_SYSRULES_richTextDisplayField"(
                              value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                                text: "ASK",
                                color: "ACCENT",
                                style: "STRONG"
                              ),
                              align: "CENTER"
                            )
                          }
                        )
                      ),
                      #"SYSTEM_SYSRULES_columnLayout"(
                        contents: #"SYSTEM_SYSRULES_cardLayout"(
                          contents: {
                            #"SYSTEM_SYSRULES_richTextDisplayField"(
                              value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                                text: length(local!actualCoreAsks),
                                color: if(
                                  length(local!actualCoreAsks) < local!plannedCoreAsks,
                                  "NEGATIVE",
                                  "POSITIVE"
                                ),
                                size: "LARGE",
                                style: "STRONG"
                              ),
                              align: "CENTER"
                            ),
                            #"SYSTEM_SYSRULES_richTextDisplayField"(
                              value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                                text: "Confirmed/In Process",
                                color: "ACCENT",
                                style: "STRONG"
                              ),
                              align: "CENTER"
                            )
                          }
                        )
                      )
                    }
                  )
                }
              ),
              width: "MEDIUM_PLUS"
            ),
            #"SYSTEM_SYSRULES_columnLayout"()
          }
        ),
        #"SYSTEM_SYSRULES_pieChartField"(
          series: {
            #"SYSTEM_SYSRULES_chartSeries"(
              label: "Confirmed",
              data: local!completedCoreAsks
            ),
            #"SYSTEM_SYSRULES_chartSeries"(
              label: "In Process",
              data: local!inprocessCoreAsks
            ),
            if(
              local!plannedCoreAsks - length(local!actualCoreAsks) > 0,
              #"SYSTEM_SYSRULES_chartSeries"(
                label: "Open",
                data: local!plannedCoreAsks - length(local!actualCoreAsks)
              ),
              {}
            )
          },
          showDataLabels: true,
          colorScheme: #"SYSTEM_SYSRULES_colorSchemeCustom"(colors: { #"_a-0000e825-ace1-8000-9c24-011c48011c48_6777992", #"_a-0000e825-ace1-8000-9c24-011c48011c48_6778342", #"_a-0000e825-ace1-8000-9c24-011c48011c48_6778348" }),
          style: "PIE",
          seriesLabelStyle: "LEGEND",
          height: "MEDIUM"
        )
      }
    ),
    #"SYSTEM_SYSRULES_sectionLayout_v1"(
      label: "Core ASKs by Group",
      contents: {
        #"SYSTEM_SYSRULES_cardLayout"(
          contents: {
            #"SYSTEM_SYSRULES_columnChartField"(
              label: local!fiscalYearLabel & " " & "Core ASKs by Group",
              instructions: "Click on the group to see a breakdown chart.",
              categories: index(local!groupChartData, "group", {}),
              series: {
                #"SYSTEM_SYSRULES_chartSeries"(
                  label: "Open", 
                  data: index(local!groupChartData, "open"),
                  links: #"SYSTEM_SYSRULES_forEach"(
                    items: index(local!groupChartData, "group", {}),
                    expression: #"SYSTEM_SYSRULES_dynamicLink"(
                      value: fv!item,
                      saveInto: {
                        a!save(local!selectedGroupName, save!value),
                        a!save(
                          local!selectedGroups,
                          #"_a-0000e825-ace1-8000-9c24-011c48011c48_6906592"(
                            group: fv!item
                          )
                        )
                      }
                    )
                  )
                ),
                #"SYSTEM_SYSRULES_chartSeries"(
                  label: "In Process", 
                  data: index(local!groupChartData, "inProcess"),
                  links: #"SYSTEM_SYSRULES_forEach"(
                    items: index(local!groupChartData, "group", {}),
                    expression: #"SYSTEM_SYSRULES_dynamicLink"(
                      value: fv!item,
                      saveInto: {
                        a!save(local!selectedGroupName, save!value),
                        a!save(
                          local!selectedGroups,
                          #"_a-0000e825-ace1-8000-9c24-011c48011c48_6906592"(
                            group: fv!item
                          )
                        )
                      }
                    )
                  )
                ),
                #"SYSTEM_SYSRULES_chartSeries"(
                  label: "Confirmed", 
                  data: index(local!groupChartData, "confirmed"),
                  links: #"SYSTEM_SYSRULES_forEach"(
                    items: index(local!groupChartData, "group", {}),
                    expression: #"SYSTEM_SYSRULES_dynamicLink"(
                      value: fv!item,
                      saveInto: {
                        a!save(local!selectedGroupName, save!value),
                        a!save(
                          local!selectedGroups,
                          #"_a-0000e825-ace1-8000-9c24-011c48011c48_6906592"(
                            group: fv!item
                          )
                        )
                      }
                    )
                  )
                )
              },
              xAxisTitle: "",
              stacking: "NORMAL",
              showLegend: true,
              showDataLabels: true,
              colorScheme: #"SYSTEM_SYSRULES_colorSchemeCustom"(colors: { #"_a-0000e825-ace1-8000-9c24-011c48011c48_6778348", #"_a-0000e825-ace1-8000-9c24-011c48011c48_6778342", #"_a-0000e825-ace1-8000-9c24-011c48011c48_6777992" })
            ),
            #"SYSTEM_SYSRULES_gridField_v1"(
              label: local!fiscalYearLabel & " " & "Core ASKs by Group",
              data: local!groupChartData,
              columns: {
                #"SYSTEM_SYSRULES_gridColumn"(label: "Group", sortField: "group", value: index(fv!row, "group"), width: "2X"),
                #"SYSTEM_SYSRULES_gridColumn"(label: "Plan", sortField: "plan", value: index(fv!row, "plan"), align: "END", width: "1X"),
                #"SYSTEM_SYSRULES_gridColumn"(label: "Confirmed", sortField: "confirmed", value: index(fv!row, "confirmed"), align: "END", width: "1X"),
                #"SYSTEM_SYSRULES_gridColumn"(label: "In Process", sortField: "inProcess", value: index(fv!row, "inProcess"), align: "END", width: "1X"),
                #"SYSTEM_SYSRULES_gridColumn"(label: "Total Confirmed and In Process", value: sum(index(fv!row, "confirmed"), index(fv!row, "inProcess")), align: "END", width: "1X"),
                #"SYSTEM_SYSRULES_gridColumn"(label: "Open", sortField: "open", value: index(fv!row, "open"), align: "END", width: "1X")
              }
            )
          },
          padding: "STANDARD",
          showBorder: false
        )
      }
    ),
    #"SYSTEM_SYSRULES_sectionLayout_v1"(
      label: local!selectedGroupName & " " & "Core ASKs by Level",
      showWhen: a!isNotNullOrEmpty(local!selectedGroups),
      contents: {
        #"SYSTEM_SYSRULES_cardLayout"(
          contents: {
            #"SYSTEM_SYSRULES_columnChartField"(
              label: local!fiscalYearLabel & " " & local!selectedGroupName & " " & "Core ASKs by Level",
              categories: index(local!groupSpecificChartData, "level", {}),
              series: {
                #"SYSTEM_SYSRULES_chartSeries"(label: "Open", data: index(local!groupSpecificChartData, "open")),
                #"SYSTEM_SYSRULES_chartSeries"(label: "In Process", data: index(local!groupSpecificChartData, "inProcess")),
                #"SYSTEM_SYSRULES_chartSeries"(label: "Confirmed", data: index(local!groupSpecificChartData, "confirmed"))
              },
              xAxisTitle: "",
              stacking: "NORMAL",
              showLegend: true,
              showDataLabels: true,
              colorScheme:  #"SYSTEM_SYSRULES_colorSchemeCustom"(colors: { #"_a-0000e825-ace1-8000-9c24-011c48011c48_6778348", #"_a-0000e825-ace1-8000-9c24-011c48011c48_6778342", #"_a-0000e825-ace1-8000-9c24-011c48011c48_6777992" })
            ),
            #"SYSTEM_SYSRULES_gridField_v1"(
              label: local!fiscalYearLabel & " " & local!selectedGroupName & " " & "Core ASKs by Level",
              data: local!groupSpecificChartData,
              columns: {
                #"SYSTEM_SYSRULES_gridColumn"(label: "Level", sortField: "level", value: index(fv!row, "level"), width: "2X"),
                #"SYSTEM_SYSRULES_gridColumn"(label: "Plan", sortField: "plan", value: index(fv!row, "plan"), align: "END", width: "1X"),
                #"SYSTEM_SYSRULES_gridColumn"(label: "Confirmed", sortField: "confirmed", value: index(fv!row, "confirmed"), align: "END", width: "1X"),
                #"SYSTEM_SYSRULES_gridColumn"(label: "In Process", sortField: "inProcess", value: index(fv!row, "inProcess"), align: "END", width: "1X"),
                #"SYSTEM_SYSRULES_gridColumn"(label: "Total Confirmed and In Process", value: sum(index(fv!row, "confirmed"), index(fv!row, "inProcess")), align: "END", width: "1X"),
                #"SYSTEM_SYSRULES_gridColumn"(label: "Open", sortField: "open", value: index(fv!row, "open"), align: "END", width: "1X")
              }
            )
          },
          padding: "STANDARD",
          showBorder: false
        )
      }
    ),
    #"SYSTEM_SYSRULES_sectionLayout_v1"(
      label: "Core ASKs by Level",
      contents: {
        #"SYSTEM_SYSRULES_cardLayout"(
          contents: {
            #"SYSTEM_SYSRULES_columnChartField"(
              label: local!fiscalYearLabel & " " & "Core ASKs by Level",
              categories: index(local!levelChartData, "level", {}),
              series: {
                #"SYSTEM_SYSRULES_chartSeries"(label: "Open", data: index(local!levelChartData, "open")),
                #"SYSTEM_SYSRULES_chartSeries"(label: "In Process", data: index(local!levelChartData, "inProcess")),
                #"SYSTEM_SYSRULES_chartSeries"(label: "Confirmed", data: index(local!levelChartData, "confirmed"))
              },
              xAxisTitle: "",
              stacking: "NORMAL",
              showLegend: true,
              showDataLabels: true,
              colorScheme: #"SYSTEM_SYSRULES_colorSchemeCustom"(colors: { #"_a-0000e825-ace1-8000-9c24-011c48011c48_6778348", #"_a-0000e825-ace1-8000-9c24-011c48011c48_6778342", #"_a-0000e825-ace1-8000-9c24-011c48011c48_6777992" })
            ),
            #"SYSTEM_SYSRULES_gridField_v1"(
              label: local!fiscalYearLabel & " " & "Core ASKs by Level",
              data: local!levelChartData,
              columns: {
                #"SYSTEM_SYSRULES_gridColumn"(label: "Level", sortField: "level", value: index(fv!row, "level"), width: "2X"),
                #"SYSTEM_SYSRULES_gridColumn"(label: "Plan", sortField: "plan", value: index(fv!row, "plan"), align: "END", width: "1X"),
                #"SYSTEM_SYSRULES_gridColumn"(label: "Confirmed", sortField: "confirmed", value: index(fv!row, "confirmed"), align: "END", width: "1X"),
                #"SYSTEM_SYSRULES_gridColumn"(label: "In Process", sortField: "inProcess", value: index(fv!row, "inProcess"), align: "END", width: "1X"),
                #"SYSTEM_SYSRULES_gridColumn"(label: "Total Confirmed and In Process", value: sum(index(fv!row, "confirmed"), index(fv!row, "inProcess")), align: "END", width: "1X"),
                #"SYSTEM_SYSRULES_gridColumn"(label: "Open", sortField: "open", value: index(fv!row, "open"), align: "END", width: "1X")
              }
            )
          },
          padding: "STANDARD",
          showBorder: false
        )
      }
    )
  }
)
